def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_metadata = version.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in version_without_metadata:
            core_part, prerelease_part = version_without_metadata.split('-', 1)
        else:
            core_part = version_without_metadata
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        major, minor, patch = map(int, core_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_sort_key(prerelease_identifiers):
        if prerelease_identifiers is None:
            # No pre-release sorts after pre-release
            return (1, [])
        else:
            # Has pre-release sorts before no pre-release
            converted = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    # Numeric identifiers: (0, numeric_value)
                    converted.append((0, int(identifier)))
                else:
                    # Non-numeric identifiers: (1, string_value)
                    converted.append((1, identifier))
            return (0, converted)

    def sort_key(indexed_version):
        index, version = indexed_version
        major, minor, patch, prerelease = parse_version(version)
        return (major, minor, patch, prerelease_sort_key(prerelease), index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [version for _, version in sorted_versions]

